package com.gerenciadorrural.modules.herd.application;
import com.fasterxml.jackson.databind.ObjectMapper; import com.gerenciadorrural.modules.herd.domain.*; import com.gerenciadorrural.shared.tenancy.*; import org.springframework.stereotype.Service; import java.math.*; import java.time.*; import java.util.*;
@Service public class ManageHerdIntelligence {private static final Set<String> W=Set.of("OWNER","ADMIN","MANAGER","OPERATOR"); private final TenantTransactionExecutor tx;private final HerdAnimalProfileRepository animals;private final HerdManagementRepository repo;private final AnimalEventRepository events;private final ObjectMapper json;private final Clock clock; public ManageHerdIntelligence(TenantTransactionExecutor tx,HerdAnimalProfileRepository a,HerdManagementRepository r,AnimalEventRepository e,ObjectMapper j,Clock c){this.tx=tx;animals=a;repo=r;events=e;json=j;clock=c;}
 public Result weights(TenantContext c,UUID op,List<WeightCommand> xs){return run(c,op,"WEIGHT",xs,null);} public Result health(TenantContext c,UUID op,HealthTreatmentType type,LocalDate day,String product,String protocol,LocalDate due,String notes,List<? extends AnimalCommand> xs){if(type==null||day==null||day.isAfter(LocalDate.now(clock))||(due!=null&&due.isBefore(day)))bad();return run(c,op,"HEALTH",xs,new Health(type,day,text(product,160),text(protocol,160),due,text(notes,1000)));}
 public Page<HerdManagementRepository.Weight> weightHistory(TenantContext c,UUID id,int page,int size){if(page<0||size<1||size>100||(long)page*size>Integer.MAX_VALUE)bad();return tx.execute(c,()->{exists(c,id);return new Page<>(repo.weights(c.tenantId(),c.farmId(),id,size,(long)page*size),page,size,repo.weightCount(c.tenantId(),c.farmId(),id));});}
 public Page<HerdManagementRepository.Treatment> treatmentHistory(TenantContext c,UUID id,int page,int size){if(page<0||size<1||size>100||(long)page*size>Integer.MAX_VALUE)bad();return tx.execute(c,()->{exists(c,id);return new Page<>(repo.treatments(c.tenantId(),c.farmId(),id,size,(long)page*size),page,size,repo.treatmentCount(c.tenantId(),c.farmId(),id));});}
 private Result run(TenantContext c,UUID op,String kind,List<? extends AnimalCommand> input,Health health){if(!W.contains(c.role()))throw new HerdMovementForbiddenException();if(op==null||input==null||input.isEmpty()||input.size()>100)bad();var xs=new ArrayList<>(input); if(xs.stream().anyMatch(Objects::isNull))bad(); xs.sort(Comparator.comparing(x->x.id().toString()));Set<UUID> ids=new HashSet<>();for(var x:xs){if(x.id()==null||x.expectedVersion()<0||!ids.add(x.id()))bad();if(x instanceof WeightCommand w&&(w.weightKg()==null||w.weightKg().signum()<=0||w.weightKg().scale()>3||w.weightKg().precision()>8||w.measuredOn()==null||w.measuredOn().isAfter(LocalDate.now(clock))))bad();}String canonical=canon(kind,xs,health);return tx.execute(c,()->{events.lockOperation(c.tenantId(),c.farmId(),op);var old=repo.operation(c.tenantId(),c.farmId(),op);if(old.isPresent()){if(!old.get().equals(canonical))throw new HerdOperationIdempotencyConflictException();return new Result(op,xs.stream().map(x->new AnimalResult(x.id(),x.expectedVersion()+1)).toList(),true);}for(var x:xs){var a=animals.findByIdForCorrection(c.tenantId(),c.farmId(),x.id()).orElseThrow(HerdAnimalNotFoundException::new);if(a.version()!=x.expectedVersion())throw new HerdAnimalVersionConflictException();if(a.status()!=HerdAnimalStatus.ACTIVE)throw new HerdLifecycleConflictException();}repo.saveOperation(c.tenantId(),c.farmId(),op,kind,canonical);var result=new ArrayList<AnimalResult>();for(var x:xs){var a=animals.touch(c.tenantId(),c.farmId(),x.id(),x.expectedVersion()).orElseThrow(HerdAnimalVersionConflictException::new);result.add(new AnimalResult(x.id(),a.version()));if(x instanceof WeightCommand w){String notes=text(w.notes(),1000);repo.weight(c.tenantId(),c.farmId(),x.id(),op,w.measuredOn(),w.weightKg().stripTrailingZeros(),notes,c.userId());events.record(c.tenantId(),c.farmId(),x.id(),AnimalEventType.WEIGHED,op,c.userId(),w.measuredOn(),a.version(),new WeighedEventDetails(w.weightKg().stripTrailingZeros(),notes));}else {repo.treatment(c.tenantId(),c.farmId(),x.id(),op,health.type,health.day,health.product,health.protocol,health.due,health.notes,c.userId());events.record(c.tenantId(),c.farmId(),x.id(),AnimalEventType.HEALTH_TREATMENT,op,c.userId(),health.day,a.version(),new HealthTreatmentEventDetails(health.type,health.product,health.protocol,health.due,health.notes));}}return new Result(op,List.copyOf(result),false);});}
 private void exists(TenantContext c,UUID id){if(id==null||animals.findById(c.tenantId(),c.farmId(),id).isEmpty())throw new HerdAnimalNotFoundException();} private String canon(String k,List<? extends AnimalCommand>x,Health h){try{var root=new TreeMap<String,Object>();root.put("kind",k);root.put("health",h);root.put("animals",x.stream().map(a->{var item=new TreeMap<String,Object>();item.put("animalId",a.id().toString());item.put("expectedVersion",a.expectedVersion());if(a instanceof WeightCommand w){item.put("measuredOn",w.measuredOn().toString());item.put("weightKg",w.weightKg().stripTrailingZeros().toPlainString());item.put("notes",text(w.notes(),1000));}return item;}).toList());return json.writeValueAsString(root);}catch(Exception e){throw new IllegalStateException(e);}}private static String text(String x,int n){if(x==null)return null;String y=x.strip();if(y.isEmpty()||y.indexOf('\0')>=0||y.codePointCount(0,y.length())>n)bad();return y;}private static void bad(){throw new HerdAnimalCommandInvalidException();} public interface AnimalCommand {UUID id();long expectedVersion();} public record BasicAnimalCommand(UUID id,long expectedVersion) implements AnimalCommand{} public record WeightCommand(UUID id,long expectedVersion,BigDecimal weightKg,LocalDate measuredOn,String notes) implements AnimalCommand{} public record Page<T>(List<T> items,int page,int size,long totalElements){} public record Result(UUID operationId,List<AnimalResult> animals,boolean replayed){} public record AnimalResult(UUID animalId,long resultingVersion){} private record Health(HealthTreatmentType type,LocalDate day,String product,String protocol,LocalDate due,String notes){}
}
